#include <iostream>
#include <string>
using namespace std;

struct Aluno {                 // um novo tipo, com três campos
    string nome;
    int matricula;
    double nota;
};

int main() {
    Aluno a;
    a.nome = "Ana";
    a.matricula = 2026001;
    a.nota = 8.5;
    Aluno b = {"Bruno", 2026002, 7.0};   // todos de uma vez
    cout << a.nome << " (" << a.matricula << "): " << a.nota
         << endl;                         // Ana (2026001): 8.5
    Aluno c = a;                          // copia tudo
